use super::*;
use crate::typed_operation_page::{TypedOperationResultPage,TypedOperationResultLane,TYPED_OPERATION_RESULT_PAGE_BYTES};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;

fn corpus()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn original()->RetainedCloneGrant{let law=corpus();let g=&law["originalHost"];RetainedCloneGrant{maximum_items:g["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize}}
fn denied(d:RetirementDemand,g:RetainedCloneGrant)->Vec<RetainedCloneGrant>{let mut grants=vec![RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g}];if d.copy_bytes>0{grants.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g})}if d.capacity_bytes>0{grants.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g})}if d.release_bytes>0{grants.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g})}grants}
fn receipt(p:RetainedCloneProgress,heap:semio_framework_trace::HeapAllocationObservation,g:RetainedCloneGrant){assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));}
fn token()->TypedOperationResultToken{TypedOperationResultToken{receiver:1,operation:7,generation:2,sequence:3,attempt:1}}
fn descriptor_source(length:usize)->(TypedOperationResultPage,ResultPageDelivery){let g=original();let mut page=TypedOperationResultPage::from_original(token(),TypedOperationResultLane::Artifact,vec![90;TYPED_OPERATION_RESULT_PAGE_BYTES],length);let pointer=page.bytes().as_ptr();let mut slot=None;for _ in 0..2{let((next,p),heap)=observe(||page.present(g).unwrap());receipt(p,heap,g);if next.is_some(){slot=next;}}assert_eq!(slot.as_ref().unwrap().bytes().as_ptr(),pointer);let((mut source,p),heap)=observe(||ResultPageDelivery::capture(&mut slot,g).unwrap().unwrap());receipt(p,heap,g);let(step,heap)=observe(||source.advance(g).unwrap());receipt(step.progress(),heap,g);assert!(source.ready());assert_eq!(source.body().unwrap().as_ptr(),pointer);(page,source)}
fn close_page(page:&mut TypedOperationResultPage,g:RetainedCloneGrant){for _ in 0..10000{if page.terminal_is_empty(){return;}let(step,heap)=observe(||page.close_step(g).unwrap());receipt(step.progress(),heap,g);assert_ne!(step.progress(),Default::default());}panic!("original producer page close stalled");}
fn retire_wire(wire:Vec<u8>,g:RetainedCloneGrant){let mut owner=ControlledRetirement::new(wire).unwrap_or_else(|_|panic!("original bytes support controlled retirement"));for _ in 0..10000{if owner.terminal_is_empty(){return;}let(step,heap)=observe(||owner.step(g).unwrap());receipt(step.progress(),heap,g);assert_ne!(step.progress(),Default::default());}panic!("original returned wire close stalled");}
fn close_receiver(receiver:&mut ResultPageWireReceiver,g:RetainedCloneGrant){receiver.begin_close();for _ in 0..10000{if receiver.terminal_is_empty(){return;}let d=receiver.next_close_demand(g.maximum_copy_bytes).unwrap();assert!(fits(d,g));for refusal in denied(d,g){let(step,heap)=observe(||receiver.close_step(refusal).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(step,heap)=observe(||receiver.close_step(g).unwrap());receipt(step.progress(),heap,g);assert_ne!(step.progress(),Default::default());}panic!("original receiver cancellation stalled");}
fn golden(row:&serde_json::Value)->Vec<u8>{let text=row["headerHex"].as_str().unwrap();let mut bytes=(0..text.len()).step_by(2).map(|i|u8::from_str_radix(&text[i..i+2],16).unwrap()).collect::<Vec<_>>();bytes.resize(bytes.len()+row["bodyBytes"].as_u64().unwrap()as usize,row["fill"].as_u64().unwrap()as u8);bytes}

/// 📥️ The actual receiving owner preserves exact original ABI bytes and all physical currencies.
#[test]
fn original_host_wire_receiver_preserves_golden_bytes_and_physical_receipts(){let law=corpus();let g=original();assert_eq!((g.maximum_copy_bytes,g.maximum_capacity_bytes,g.maximum_release_bytes,g.maximum_depth),(4096,65536,262144,64));for row in law["cases"].as_array().unwrap(){let length=row["bodyBytes"].as_u64().unwrap()as usize;let(mut page,source)=descriptor_source(length);let pointer=page.bytes().as_ptr();let mut slot=Some(source);for refusal in denied(ResultPageWireReceiver::capture_demand(),g){let(result,heap)=observe(||ResultPageWireReceiver::capture(&mut slot,refusal).unwrap());assert!(result.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(slot.as_ref().unwrap().body().unwrap().as_ptr(),pointer);}let((mut receiver,p),heap)=observe(||ResultPageWireReceiver::capture(&mut slot,g).unwrap().unwrap());receipt(p,heap,g);assert!(slot.is_none());let mut turns=0;while !receiver.ready(){let(result,heap)=observe(||receiver.take_wire(g));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let d=receiver.next_demand(g.maximum_copy_bytes).unwrap();assert!(fits(d,g));let stage=receiver.stage;let owned=receiver.wire.as_ref().unwrap().as_ptr();let copied=receiver.wire.as_ref().unwrap().len();for refusal in denied(d,g){let(step,heap)=observe(||receiver.advance(refusal).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(receiver.stage==stage);assert_eq!((receiver.wire.as_ref().unwrap().as_ptr(),receiver.wire.as_ref().unwrap().len()),(owned,copied));assert_eq!(page.bytes().as_ptr(),pointer);}let(step,heap)=observe(||receiver.advance(g).unwrap());receipt(step.progress(),heap,g);assert_eq!(page.bytes().as_ptr(),pointer);assert_eq!(receiver.token(),token());turns+=1;assert!(turns<1000);}assert!(receiver.source.is_none());for refusal in denied(receiver.take_demand().unwrap(),g){let(result,heap)=observe(||receiver.take_wire(refusal).unwrap());assert!(result.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(receiver.ready());}let((wire,p),heap)=observe(||receiver.take_wire(g).unwrap().unwrap());receipt(p,heap,g);assert_eq!(wire,golden(row));assert_eq!(wire.len(),TYPED_OPERATION_RESULT_HEADER_BYTES+length);if length==4096{assert!(wire.capacity()>4096);}assert!(receiver.terminal_is_empty());retire_wire(wire,g);close_page(&mut page,g);let(_,heap)=observe(||drop(receiver));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] actual original wire receiving {}: turns={turns}, golden header/body, original pointer, all5 denied0heap, output after source close, actual cap/release and terminalDrop0",row["name"]);}}

/// 🛑️ Every actual allocation, copy and source-close action prefix cancels with exact physical cleanup.
#[test]
fn original_host_wire_receiver_cancels_every_actual_action_prefix(){let law=corpus();let g=original();for row in law["cases"].as_array().unwrap(){let length=row["bodyBytes"].as_u64().unwrap()as usize;let(mut page,source)=descriptor_source(length);let mut slot=Some(source);let(mut receiver,_)=ResultPageWireReceiver::capture(&mut slot,g).unwrap().unwrap();let mut total=0;while !receiver.ready(){receiver.advance(g).unwrap();total+=1;assert!(total<1000);}close_receiver(&mut receiver,g);close_page(&mut page,g);for cut in 0..=total{let(mut page,source)=descriptor_source(length);let pointer=page.bytes().as_ptr();let mut slot=Some(source);let((mut receiver,p),heap)=observe(||ResultPageWireReceiver::capture(&mut slot,g).unwrap().unwrap());receipt(p,heap,g);for _ in 0..cut{let(step,heap)=observe(||receiver.advance(g).unwrap());receipt(step.progress(),heap,g);assert_eq!(page.bytes().as_ptr(),pointer);}close_receiver(&mut receiver,g);assert!(receiver.take_wire(g).is_err());close_page(&mut page,g);let(_,heap)=observe(||drop(receiver));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] actual original wire receiving {} cancellation prefix {cut}/{total}: all5 denied0heap, original alias and partial destination closed, no output, terminalDrop0",row["name"]);}}}
